#include <vector>
#include <cstdint>

// Returns the maximum possible score for the coloring problem described.
// The score is simply the sum of a[i-1] for every i where a[i-1] == a[i],
// because any valid coloring (including all same color) achieves this,
// and no coloring can exceed it.
long long maxColoringScore(const std::vector<long long>& a) {
    long long score = 0;
    for (std::size_t i = 1; i < a.size(); ++i) {
        if (a[i - 1] == a[i]) {
            score += a[i - 1];
        }
    }
    return score;
}

#include <cassert>
#include <vector>

// (The solution function is included here for the test to compile.)
long long maxColoringScore(const std::vector<long long>& a) {
    long long score = 0;
    for (std::size_t i = 1; i < a.size(); ++i) {
        if (a[i - 1] == a[i]) {
            score += a[i - 1];
        }
    }
    return score;
}

int main() {
    // Basic cases
    assert(maxColoringScore({5}) == 0);
    assert(maxColoringScore({5, 5}) == 5);
    assert(maxColoringScore({5, 6}) == 0);
    assert(maxColoringScore({1, 2, 2, 3, 3, 3}) == (2 + 3 + 3)); // 8

    // Longer sequence with duplicates
    std::vector<long long> v1 = {1, 1, 1, 1};
    assert(maxColoringScore(v1) == (1 + 1 + 1)); // 3

    // No equal adjacent
    std::vector<long long> v2 = {1, 2, 3, 4};
    assert(maxColoringScore(v2) == 0);

    // Large values
    std::vector<long long> v3 = {1000000000LL, 1000000000LL, 1, 1};
    assert(maxColoringScore(v3) == (1000000000LL + 1)); // 1000000001

    // Mixed pattern
    std::vector<long long> v4 = {1, 2, 2, 3, 2, 2, 4};
    // Pairs: (2,2) at i=2, (2,2) at i=5 -> contributions 2+2=4
    assert(maxColoringScore(v4) == 4);

    // Sorted duplicates
    std::vector<long long> v5 = {1, 2, 3, 3, 4, 4, 5, 5};
    assert(maxColoringScore(v5) == (3 + 4 + 5)); // 12

    return 0;
}
